CREATE OR REPLACE FUNCTION public.integration_yida_generated_layout_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := clock_timestamp();
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'YIDA_GENERATED_LAYOUT_IMMUTABLE';
END;
$function$
